public class InnerCollaborationMLPaymentConfigFactory(Action<Humidifier.CleanRooms.CollaborationTypes.MLPaymentConfig> factoryAction = null) : SubResourceFactory<Humidifier.CleanRooms.CollaborationTypes.MLPaymentConfig>
{

    internal InnerCollaborationModelInferencePaymentConfigFactory ModelInferenceFactory { get; set; }

    internal InnerCollaborationSyntheticDataGenerationPaymentConfigFactory SyntheticDataGenerationFactory { get; set; }

    internal InnerCollaborationModelTrainingPaymentConfigFactory ModelTrainingFactory { get; set; }

    protected override Humidifier.CleanRooms.CollaborationTypes.MLPaymentConfig Create()
    {
        var mLPaymentConfigResult = CreateMLPaymentConfig();
        factoryAction?.Invoke(mLPaymentConfigResult);

        return mLPaymentConfigResult;
    }

    private Humidifier.CleanRooms.CollaborationTypes.MLPaymentConfig CreateMLPaymentConfig()
    {
        var mLPaymentConfigResult = new Humidifier.CleanRooms.CollaborationTypes.MLPaymentConfig();

        return mLPaymentConfigResult;
    }
    public override void CreateChildren(Humidifier.CleanRooms.CollaborationTypes.MLPaymentConfig result)
    {
        base.CreateChildren(result);

        result.ModelInference ??= ModelInferenceFactory?.Build();
        result.SyntheticDataGeneration ??= SyntheticDataGenerationFactory?.Build();
        result.ModelTraining ??= ModelTrainingFactory?.Build();
    }

} // End Of Class

